//! Il servizio attraversa il montaggio vero e scompare col suo owner.
use camino::Utf8PathBuf;
use fub_abi::{DocId, HostApi, PluginError, PluginManifest, ServiceProvider};
use fub_format_sheet::service::{EVALUATE_METHOD, SERVICE_ID};
use fub_host::{Host, NoWatcher};
use fub_kernel::Trust;
use serde_json::json;

#[test]
fn mounted_service_is_versioned_and_owned_by_the_bundle() {
    let dir = tempfile::tempdir().unwrap();
    let root = Utf8PathBuf::from_path_buf(dir.path().to_owned()).unwrap();
    let host = Host::new().with_watcher(Box::new(NoWatcher));
    host.open(&root).unwrap();
    host.wait_indexed(None).unwrap();
    let args = json!({"source":r#"{"version":1,"sheets":[]}"#});
    assert_eq!(
        host.call_service(None, SERVICE_ID, EVALUATE_METHOD, args.clone())
            .unwrap(),
        json!({"cells":[],"dependencies":[]})
    );
    assert!(matches!(
        host.call_service(None, SERVICE_ID, "evaluate_v2", args.clone()),
        Err(PluginError::BadArgs(_))
    ));
    assert!(host
        .set_plugin_enabled(None, SERVICE_ID, false)
        .unwrap()
        .is_empty());
    assert!(matches!(
        host.call_service(None, SERVICE_ID, EVALUATE_METHOD, args.clone()),
        Err(PluginError::Unserved(_))
    ));
    assert!(host
        .set_plugin_enabled(None, SERVICE_ID, true)
        .unwrap()
        .is_empty());
    assert!(host
        .call_service(None, SERVICE_ID, EVALUATE_METHOD, args)
        .is_ok());
}

struct ReadProbe;
impl ServiceProvider for ReadProbe {
    fn call(
        &self,
        _: &str,
        _: &str,
        _: serde_json::Value,
        host: &mut dyn HostApi,
    ) -> Result<serde_json::Value, PluginError> {
        host.read_document(&DocId::new("private.md"))?;
        Ok(json!("must not be reached"))
    }
}

#[test]
fn shell_call_does_not_lend_its_privileges_to_the_service() {
    let dir = tempfile::tempdir().unwrap();
    let root = Utf8PathBuf::from_path_buf(dir.path().to_owned()).unwrap();
    std::fs::write(root.join("private.md"), "private").unwrap();
    let host = Host::new().with_watcher(Box::new(NoWatcher));
    host.open(&root).unwrap();
    host.wait_indexed(None).unwrap();
    let workspace = host.debug_workspace(None).unwrap();
    {
        let mut ws = workspace.write().unwrap();
        ws.register_plugin(
            PluginManifest::new("com.example.audit", "Unprivileged")
                .providing(&["com.example.audit:sheet"]),
            Trust::Community,
        )
        .unwrap();
        ws.register_service_provider("com.example.audit", Box::new(ReadProbe))
            .unwrap();
    }
    assert!(matches!(
        host.call_service(None, "com.example.audit:sheet", "read", json!(null)),
        Err(PluginError::PermissionDenied(_))
    ));
}
